  "claim": {
    "component_id": "C047.component",
    "value": "Later evidence should trigger a dated revision of the account.",
    "scope": "A conditional revision instruction in the reporting-cutoff context; no later evidence is asserted to exist.",
    "provenance": {
      "refs": [
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly supplies the revision instruction, dating requirement and reporting-cutoff qualification."
    }
  },
  "signal_basis": {
    "component_id": "C047.signal_basis",
    "value": "Reconstruction can stop at the reporting cutoff with unresolved gaps. The account records established transitions, contradictions and remaining gaps; the cutoff does not resolve the underlying uncertainty.",
    "scope": "The case-level account at the investigation's stopping point; later evidence remains a conditional possibility.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans establish the stopping conditions, the account's evidentiary contents and the persistence of uncertainty beyond the cutoff."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C047.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to license this bounded procedural instruction."
    }
  },
  "rationale": "Because the account reflects evidence available at a stopping point that does not settle remaining uncertainty, later evidence warrants a dated revision to keep that account aligned with its evidentiary basis. The claim requires revision, without prescribing what substantive conclusion later evidence must support.",
  "uncertainty": "Neither the existence nor the implications of later evidence are asserted.",
  "anomalies": []
}
